use super::*;
fn valid_uuid(id:&str)->bool { id.len()==36&&id.bytes().enumerate().all(|(i,c)|if [8,13,18,23].contains(&i){c==b'-'}else{c.is_ascii_hexdigit()}) }
pub fn through(raw:Option<&str>)->Result<String,String>{match raw{Some(s)=>{chrono::DateTime::parse_from_rfc3339(s).map_err(|_|"Data de leitura inválida.".to_string())?;Ok(s.into())},None=>Ok(chrono::Utc::now().to_rfc3339())}}
fn matches(row:&Value,fields:&Value)->bool{fields.as_object().is_some_and(|map|map.iter().all(|(key,value)|row.get(key)==Some(value)||(value.is_null()&&row.get(key).is_none())))}
pub async fn send(state:&AppState,session:&Session,group:bool,target:&str,text:&str,media:Option<&str>,message_id:Option<&str>)->Result<Value,String>{
 let table=if group{"clt_chat_group_messages"}else{"clt_chat_messages"};let target_key=if group{"group_id"}else{"destinatario_id"};let media_key=if group{"midia_path"}else{"midia_url"};
 let mut fields=json!({"remetente_id":session.user.id,"texto":text});fields[target_key]=json!(target);fields[media_key]=json!(media);
 let lookup=if let Some(id)=message_id{if !valid_uuid(id){return Err("Identificador de envio inválido.".into())}fields["id"]=json!(id);Some(format!("/rest/v1/{table}?select=*&id=eq.{id}&remetente_id=eq.{}&{target_key}=eq.{target}&limit=1",session.user.id))}else{None};
 if let Some(path)=&lookup{let rows=get(&state.client,path,&session.access_token).await?;if let Some(row)=rows.as_array().and_then(|a|a.first()){return if matches(row,&fields){Ok(rows)}else{Err("Este envio já foi usado para outra mensagem.".into())}}}
 let result=async{let response=state.client.post(format!("{SUPABASE_URL}/rest/v1/{table}?select=*")).header("apikey",SUPABASE_KEY).bearer_auth(&session.access_token).header("content-type","application/json").header("prefer","return=representation").json(&fields).send().await.map_err(|_|"Não foi possível confirmar o envio.".to_string())?;let rows=value(response).await?;if rows.as_array().and_then(|a|a.first()).is_none_or(|row|!matches(row,&fields)){return Err("Envio sem confirmação.".into())}Ok(rows)}.await;
 if result.is_err(){if let Some(path)=lookup{if let Ok(rows)=get(&state.client,&path,&session.access_token).await{if rows.as_array().and_then(|a|a.first()).is_some_and(|row|matches(row,&fields)){return Ok(rows)}}}}
 result
}
#[cfg(test)] mod tests{use super::*;#[test]fn identity_is_strict(){assert!(valid_uuid("7e6ad794-67b0-4e66-8e14-d4a00d5c98dc"));assert!(!valid_uuid("x&destinatario_id=neq.any"));}#[test]fn existing_message_must_match_every_field(){let fields=json!({"id":"one","texto":"hello","destinatario_id":"bob"});assert!(matches(&json!({"id":"one","texto":"hello","destinatario_id":"bob","created_at":"now"}),&fields));assert!(!matches(&json!({"id":"one","texto":"other","destinatario_id":"bob"}),&fields));assert!(!matches(&json!({"id":"one","texto":"hello","destinatario_id":"eve"}),&fields));}#[test]fn read_time_requires_timestamp(){assert!(through(Some("2026-11-05T12:30:00Z")).is_ok());assert!(through(Some("now&lida=eq.true")).is_err());}}
